import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        # Final round: defect if opponent has been cooperative enough
        opp_c = sum(1 for (a, b) in history if b == 'C')
        return 'D' if opp_c * 2 >= n else 'C'
    last_me, last_opp = history[-1]

    # Count opponent defections overall
    opp_d = sum(1 for (a, b) in history if b == 'D')
    opp_c = n - opp_d

    # Early game: mostly cooperate, with quick retaliation on early defection
    if n < 4:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Immediate retaliation: if opponent defected last round, defect,
    # unless we already retaliated and they have a long history of cooperation
    if last_opp == 'D':
        # count consecutive opponent defections at tail
        streak = 0
        for (a, b) in reversed(history):
            if b == 'D':
                streak += 1
            else:
                break
        if streak >= 2:
            # long defection streak: stay in defection, small chance to probe
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        # single defection: retaliate, but forgive sometimes if opponent historically nice
        if opp_d <= max(1, n // 8) and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # Detect near-pure cooperator and exploit near end
    if n >= 85:
        if opp_c >= n - 2:
            if n >= 95:
                return 'D'
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    # Detect almost-always-defector
    if n >= 10 and opp_d >= n - 2:
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Mostly cooperative opponent: maintain cooperation, occasionally test
    if n >= 12 and opp_c >= int(0.85 * n):
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Recent behavior analysis
    win = min(12, n)
    recent_d = sum(1 for (a, b) in history[-win:] if b == 'D')
    recent_c = win - recent_d

    if recent_d >= win - 1:
        # Very recent defector: defend
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    if recent_c >= int(0.8 * win):
        # Recent cooperator
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    # If we defected last round and opponent still cooperated, don't keep exploiting too hard
    if last_me == 'D':
        # We just got the temptation payoff; return to cooperation to preserve mutual CC
        if rng.random() < 0.75:
            return 'C'

    # Tit-for-tat with mild forgiveness
    return 'C'
